const money = (n: number | string, currency: string) => { const code = String(currency || 'USD').toUpperCase(); try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: code, currencyDisplay: 'code', maximumFractionDigits: 2 }).format(Number(n)); } catch { return `${new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(Number(n))} ${code}`; } };
