declare global { interface Window { paypal?: any; google?: any } }
let paypalCardSdkPromise: Promise<void> | null = null;
const externalScriptPromises = new Map<string, Promise<void>>();
function loadPayPalCardSdk(clientId: string, sandbox: boolean, clientToken: string) {
  if (!clientToken) return Promise.reject(new Error('تعذر إعداد جلسة حقول PayPal الآمنة.'));
  if (window.paypal?.CardFields) return Promise.resolve();
  if (paypalCardSdkPromise) return paypalCardSdkPromise;
  paypalCardSdkPromise = new Promise<void>((resolve, reject) => {
    const script = document.createElement('script');
    script.id = 'paypal-card-fields';
    script.async = true;
    if (clientToken) script.setAttribute('data-client-token', clientToken);
    script.src = `https://www.paypal.com/sdk/js?client-id=${encodeURIComponent(clientId)}&components=buttons,card-fields,googlepay,applepay&enable-funding=card,paylater&currency=USD&intent=capture${sandbox ? '&buyer-country=US' : ''}`;
    script.onload = () => resolve();
    script.onerror = () => { paypalCardSdkPromise = null; script.remove(); reject(new Error('تعذر تحميل حقول PayPal.')); };
    document.head.appendChild(script);
  });
  return paypalCardSdkPromise;
}
function loadExternalScript(id: string, src: string) {
  const existing = document.getElementById(id) as HTMLScriptElement | null;
  if (existing?.dataset.loaded === 'true') return Promise.resolve();
  const pending = externalScriptPromises.get(id);
  if (pending) return pending;
  if (existing) existing.remove();
  const request = new Promise<void>((resolve, reject) => {
    const script = document.createElement('script'); script.id = id; script.src = src; script.async = true;
    script.onload = () => { script.dataset.loaded = 'true'; resolve(); }; script.onerror = () => { script.remove(); reject(new Error('تعذر تحميل خدمة الدفع.')); };
    document.head.appendChild(script);
  });
  externalScriptPromises.set(id, request);
  request.catch(() => externalScriptPromises.delete(id));
  return request;
}
