  const clearCache=async()=>{setCacheBusy(true);setToolError('');setToolNotice('');try{const r=await fetch(`${API}/api/admin/cache/clear`,{method:'POST',credentials:'include'});const d=await r.json();if(!r.ok)throw new Error(d.error||'تعذر مسح الكاش.');if('caches'in window){const keys=await window.caches.keys();await Promise.all(keys.map(key=>window.caches.delete(key)));}setToolNotice(`تم مسح ذاكرة أسعار الصرف المؤقتة${d.cleared?` (${d.cleared})`:''} وذاكرة Cache Storage لهذا النطاق.`);}catch(e:any){setToolError(e.message||'تعذر مسح الكاش.');}finally{setCacheBusy(false);}};
