  return <article className="sample-card" style={{ animationDelay: `${index * 60}ms` }}><button className="sample-poster-btn" onClick={onSelect} aria-label={`احجز ${event.title}`}><img src={image} alt={event.title} onError={e => { (e.currentTarget as HTMLImageElement).src = '/hero-banner.png'; }}/><span className="sample-date"><span className="icon-3d"><CalendarDays size={15}/></span>{dateParts(event.event_date)}</span></button><div className="sample-card-content"><h2>{event.title}</h2><div className="sample-meta"><span><span className="icon-3d"><MapPin size={15}/></span>{event.venue} · {event.city}</span></div><div className="sample-price">تذاكر تبدأ من {ticket ? money(ticket.price, ticket.currency) : 'قريبًا'}</div><button className="sample-book" disabled={!ticket || ticket.available === 0} onClick={onSelect}>{ticket?.available === 0 ? 'غير متاح حاليًا' : 'احجز الآن'}</button></div></article>;
