function EmailTemplateManager() {
  type TemplateKey='test'|'invoice'|'ticket';type Template={subject:string;html:string};
  const defaults=defaultEmailTemplatesJson as Record<TemplateKey,Template>;
  const [templates,setTemplates]=useState<Record<TemplateKey,Template>>(defaults);const [key,setKey]=useState<TemplateKey>('invoice');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');
  useEffect(()=>{fetch(`${API}/api/admin/settings`,{credentials:'include'}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'تعذر تحميل القوالب.');setTemplates({...defaults,...(d.email?.templates||{})});}).catch(e=>setError(e.message||'تعذر تحميل القوالب.'));},[]);
  const update=(field:keyof Template,value:string)=>setTemplates(current=>({...current,[key]:{...current[key],[field]:value}}));
  const sample:Record<string,string>={buyerName:'سارة أحمد',orderNumber:'TA-EXAMPLE-2026',displayAmount:'250.00',displayCurrency:'EGP',chargedAmount:'5.00',chargedCurrency:'USD',provider:'PayPal',message:'<p>رسالة التذكرة ومعلومات الدخول</p>',ticketList:'<ul><li>الحفلة — فئة VIP × 2</li></ul>'};
  const template=templates[key]||defaults[key];const preview=template.html.replace(/\{\{\{([A-Za-z0-9_]+)\}\}\}|\{\{([A-Za-z0-9_]+)\}\}/g,(_match,rawName,escapedName)=>sample[rawName||escapedName]||'مثال');const subjectPreview=template.subject.replace(/\{\{([A-Za-z0-9_]+)\}\}/g,(_match,name)=>sample[name]||'مثال');
  const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setNotice('');try{const response=await fetch(`${API}/api/admin/settings`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({emailTemplates:templates})});const data=await response.json();if(!response.ok)throw new Error(data.error||'تعذر حفظ قوالب البريد.');setNotice('تم حفظ القوالب. تُستخدم تلقائيًا في رسائل الاختبار والتذاكر.');}catch(e:any){setError(e.message||'تعذر حفظ القوالب.');}finally{setBusy(false);}};
  const resetTemplate=()=>{setTemplates(current=>({...current,[key]:defaults[key]}));setNotice('استُعيد التصميم الافتراضي لهذا القالب. اضغط حفظ القوالب لتطبيقه.');setError('');};
  return <section className="admin-content-card template-editor"><div className="feature-heading"><div><h3><Mail size={18}/> قوالب الرسائل ومعاينة HTML</h3><p>قوالب عربية متجاوبة بتصميم Ticket Arab. عدّل الرسالة وشاهد المعاينة قبل الحفظ.</p></div></div><form onSubmit={save}><div className="template-toolbar"><label>نوع الرسالة<select value={key} onChange={e=>{setKey(e.target.value as TemplateKey);setError('');setNotice('');}}><option value="invoice">{'\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u062f\u0641\u0639 \u0648\u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629'}</option><option value="test">رسالة اختبار</option><option value="ticket">إرسال التذكرة</option></select></label><button className="secondary-admin-btn" type="button" onClick={resetTemplate}>استعادة التصميم الافتراضي</button></div><label>عنوان الرسالة<input required maxLength={240} value={template.subject} onChange={e=>update('subject',e.target.value)}/></label><label>محتوى HTML<textarea className="template-html-input" rows={12} spellCheck={false} value={template.html} onChange={e=>update('html',e.target.value)}/></label><p className="template-variables">المتغيرات المتاحة: <code>{'{{buyerName}}'}</code> <code>{'{{orderNumber}}'}</code> <code>{'{{displayAmount}}'}</code> <code>{'{{displayCurrency}}'}</code> <code>{'{{chargedAmount}}'}</code> <code>{'{{chargedCurrency}}'}</code> <code>{'{{provider}}'}</code>. قالب التذكرة يدعم أيضًا <code>{'{{{message}}}'}</code> و<code>{'{{{ticketList}}}'}</code>.</p><div className="template-preview-head"><b>معاينة الرسالة</b><span>{subjectPreview}</span></div><iframe className="template-preview" title="معاينة رسالة البريد" sandbox="" srcDoc={preview}/>{error&&<div className="form-message" role="alert">{error}</div>}{notice&&<div className="success-message" role="status">{notice}</div>}<button className="pay-btn" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ القوالب'}</button></form></section>;
}
function SeoSettings() {
  const [seo,setSeo]=useState<any>({siteName:'',title:'',description:'',siteUrl:'',socialImage:'',faviconUrl:'',appleIconUrl:'',keywords:'',twitterHandle:'',allowIndex:true});
  const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [failed,setFailed]=useState(false);
  useEffect(()=>{fetch(`${API}/api/admin/settings`,{credentials:'include'}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'تعذر تحميل إعدادات SEO.');setSeo(d.seo);}).catch(e=>{setFailed(true);setMessage(e.message||'تعذر تحميل إعدادات SEO.');});},[]);
  const field=(key:string,label:string,type='text')=><label>{label}<input type={type} value={seo[key]||''} onChange={e=>setSeo({...seo,[key]:e.target.value})}/></label>;
  const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setFailed(false);setMessage('');try{const r=await fetch(`${API}/api/admin/settings`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({seo})});const d=await r.json();if(!r.ok)throw new Error(d.error||'تعذر حفظ الإعدادات.');setMessage('تم حفظ إعدادات الظهور والفهرسة. قد تحتاج محركات البحث إلى إعادة الزحف قبل ظهور التعديلات.');window.dispatchEvent(new Event('seo-settings-updated'));}catch(e:any){setFailed(true);setMessage(e.message||'تعذر حفظ الإعدادات.');}finally{setBusy(false);}};
  return <div className="admin-feature"><div className="feature-heading"><div><h2><Search size={19}/> تحسين الظهور في محركات البحث</h2><p>تحكم بعنوان الموقع ووصفه وصورة المشاركة والأيقونات. تُستخدم البيانات في معاينة Google والمنصات الاجتماعية.</p></div></div><form className="integration-form" onSubmit={save}><section className="admin-content-card"><h3>الهوية والعناوين</h3><div className="form-grid">{field('siteName','اسم الموقع')}{field('title','عنوان الصفحة الرئيسية')}{field('siteUrl','الرابط الأساسي للموقع','url')}</div><label>وصف الموقع<textarea rows={3} maxLength={320} value={seo.description||''} onChange={e=>setSeo({...seo,description:e.target.value})}/></label><label>كلمات مفتاحية إضافية<input value={seo.keywords||''} onChange={e=>setSeo({...seo,keywords:e.target.value})} placeholder="تذاكر، حفلات، فعاليات"/></label></section><section className="admin-content-card"><h3>صورة المشاركة والأيقونات</h3><p>استخدم روابط HTTPS عامة. صورة المشاركة يُفضّل أن تكون 1200 × 630 بكسل، والأيقونات بصيغة PNG. يمكن ترك الأيقونات فارغة لاستخدام أيقونات Ticket Arab الافتراضية.</p><label>رابط الصورة التعريفية (Open Graph / X)<input type="url" value={seo.socialImage||''} onChange={e=>setSeo({...seo,socialImage:e.target.value})} placeholder="https://example.com/social-card.jpg"/></label>{seo.socialImage&&<img className="seo-social-preview" src={seo.socialImage} alt="معاينة الصورة التعريفية"/>}<div className="form-grid">{field('faviconUrl','رابط أيقونة المتصفح (PNG)','url')}{field('appleIconUrl','رابط أيقونة أجهزة Apple (PNG)','url')}</div>{field('twitterHandle','حساب X (اختياري)')}</section><section className="admin-content-card"><h3>الفهرسة</h3><label className="check-setting"><input type="checkbox" checked={seo.allowIndex!==false} onChange={e=>setSeo({...seo,allowIndex:e.target.checked})}/> السماح لمحركات البحث بفهرسة الصفحة الرئيسية وإدراجها في sitemap</label><p>تُنشأ ملفات robots.txt و sitemap.xml تلقائيًا من هذه الإعدادات. صفحات الإدارة والدعم لا تظهر في نتائج البحث.</p></section>{message&&<div className={failed?'form-message':'success-message'} role="status">{message}</div>}<button className="pay-btn" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ إعدادات SEO'}</button></form></div>;
}

function ErrorPage({ code, onSupport, onHome }: { code: string; onSupport: () => void; onHome: () => void }) {
  const cardSetup = code === 'card-fields';
  return <div className="error-page"><main className="error-card"><span className="error-icon"><CreditCard size={25}/></span><div className="eyebrow">تعذر إكمال الطلب</div><h1>{cardSetup ? 'تعذر تحميل حقول البطاقة' : 'لم تكتمل عملية الدفع'}</h1><p>{cardSetup ? 'Card payment is unavailable for this request. Please choose another payment method or contact support.' : 'Payment could not be completed. If an order number was provided, contact support.'}</p><div className="error-actions"><button className="pay-btn" onClick={onSupport}><Headphones size={17}/> صفحة الدعم</button><a className="secondary-admin-btn" href="/">العودة إلى الصفحة الرئيسية</a></div></main></div>;
}
function SupportPage({ onClose }: { onClose: () => void }) {
  const [form, setForm] = useState({ sender_name: '', sender_email: '', subject: '', order_number: '', message: '' }); const [busy, setBusy] = useState(false); const [result, setResult] = useState(''); const [error, setError] = useState('');
  const submit = async (e: React.FormEvent) => { e.preventDefault(); setBusy(true); setError(''); try { const r = await fetch(`${API}/api/support`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); const d = await r.json(); if (!r.ok) throw new Error(d.error); setResult(d.reference); } catch (e: any) { setError(e.message || 'تعذر إرسال الرسالة. حاول مرة أخرى.'); } finally { setBusy(false); } };
  return <main className="support-page"><div className="checkout-modal support-modal"><button className="modal-close" onClick={onClose}><X size={19}/></button>{result ? <div className="success-view"><span className="success-icon"><Check/></span><div className="eyebrow">وصلتنا رسالتك</div><h2>فريق الدعم هيتابعها.</h2><p>احتفظ برقم المتابعة: <b>{result}</b></p><button className="primary-btn" onClick={onClose}>إغلاق <ArrowLeft size={16}/></button></div> : <><div className="eyebrow">نحن هنا للمساعدة</div><h2>راسل فريق الدعم</h2><p className="support-intro">اكتب تفاصيل المشكلة ورقم الطلب إن وُجد، وستصل رسالتك مباشرة إلى لوحة الإدارة.</p><form className="support-form" onSubmit={submit}><div className="form-grid"><label>الاسم<input required maxLength={160} value={form.sender_name} onChange={e => setForm({ ...form, sender_name:e.target.value })}/></label><label><span className="form-label-icon"><Mail size={16}/>البريد الإلكتروني</span><input required type="email" value={form.sender_email} onChange={e => setForm({ ...form, sender_email:e.target.value })}/></label><label>رقم الطلب <small>اختياري</small><input value={form.order_number} onChange={e => setForm({ ...form, order_number:e.target.value })}/></label><label>الموضوع<input required maxLength={180} value={form.subject} onChange={e => setForm({ ...form, subject:e.target.value })}/></label></div><label>تفاصيل المشكلة<textarea required minLength={10} maxLength={5000} value={form.message} onChange={e => setForm({ ...form, message:e.target.value })}/></label><div className="privacy-note">لا ترسل بيانات بطاقتك أو كلمات المرور في الرسالة.</div>{error && <div className="form-message">{error}</div>}<button className="pay-btn" disabled={busy}>{busy ? 'جارٍ الإرسال…' : 'إرسال إلى الدعم'}</button></form></>}</div></main>;
}
function EventEditor({ eventId, onDone }: { eventId: string; onDone: () => void }) {
  const [event,setEvent]=useState<any>(null);const [notice,setNotice]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [loading,setLoading]=useState(true);
  const normalize=(value:any)=>{const record=value?.event??value?.data?.event??value;if(!record||typeof record!=='object')throw new Error('لم يُرجع الخادم بيانات الحفلة. حدّث الصفحة أو ارجع إلى قائمة الحفلات.');const date=new Date(record.event_date);if(!record.event_date||Number.isNaN(date.getTime()))throw new Error('بيانات تاريخ الحفلة غير صالحة. ارجع إلى القائمة وحاول فتح الحفلة مرة أخرى.');return {...record,event_date:new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)};};
  const load=async()=>{setLoading(true);setError('');try{if(!eventId)throw new Error('رابط الحفلة غير مكتمل. ارجع إلى قائمة الحفلات وحاول مجددًا.');const response=await fetch(`${API}/api/admin/events/${encodeURIComponent(eventId)}`,{credentials:'include'});const data=await response.json();if(!response.ok)throw new Error(data.error||'تعذر تحميل بيانات الحفلة.');setEvent(normalize(data));}catch(e:any){setEvent(null);setError(e.message||'تعذر تحميل بيانات الحفلة.');}finally{setLoading(false);}};
  useEffect(()=>{load();},[eventId]);
  const update=(key:string,value:string)=>setEvent((current:any)=>({...current,[key]:value}));
  const uploadImage=(file?:File)=>{if(!file||!event)return;if(!file.type.startsWith('image/')||file.size>3*1024*1024){setError('اختر صورة لا يتجاوز حجمها 3 ميجابايت.');return;}const reader=new FileReader();reader.onload=()=>update('image_url',String(reader.result||''));reader.onerror=()=>setError('تعذر قراءة الصورة المختارة.');reader.readAsDataURL(file);};
  const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setNotice('');try{const eventDate=new Date(event.event_date);if(Number.isNaN(eventDate.getTime()))throw new Error('أدخل تاريخًا ووقتًا صالحين للحفلة.');const payload={...event,event_date:eventDate.toISOString()};const response=await fetch(`${API}/api/admin/events/${encodeURIComponent(eventId)}`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.error||'تعذر حفظ التعديلات.');if(data.event)setEvent(normalize(data));setNotice('تم حفظ بيانات الحفلة بنجاح.');}catch(e:any){setError(e.message||'تعذر حفظ التعديلات.');}finally{setBusy(false);}};
  if(loading)return <div className="admin-feature admin-state-card"><CalendarDays size={25}/><h2>جارٍ تحميل بيانات الحفلة</h2><p>يتم جلب تفاصيل الحفلة من قاعدة البيانات.</p></div>;
  if(!event)return <div className="admin-feature admin-state-card"><CalendarDays size={25}/><h2>تعذر فتح صفحة التعديل</h2><p>{error}</p><div className="admin-state-actions"><button className="secondary-admin-btn" onClick={onDone}>العودة إلى الحفلات</button><button className="pay-btn" onClick={load}>إعادة المحاولة</button></div></div>;
  return <div className="admin-feature event-editor-page"><div className="feature-heading"><div><h2><CalendarDays size={21}/> تعديل بيانات الحفلة</h2><p>عدّل بيانات الحفلة وصورتها في هذه الصفحة، وأدر المخزون من قسم التذاكر.</p></div><button type="button" className="secondary-admin-btn" onClick={onDone}>العودة إلى الحفلات</button></div><form className="event-form" onSubmit={save}><section className="admin-content-card"><h3>الصورة والتفاصيل</h3><div className="event-image-editor"><img src={event.image_url||'/hero-banner.png'} alt={event.title}/><label>رابط الصورة<input type="url" value={event.image_url?.startsWith('data:')?'':event.image_url||''} onChange={e=>update('image_url',e.target.value)} placeholder="https://..."/></label><label>أو اختر صورة من جهازك<input type="file" accept="image/*" onChange={e=>uploadImage(e.currentTarget.files?.[0])}/></label></div><div className="form-grid">{[['title','اسم الحفلة','text'],['venue','المكان','text'],['city','المدينة','text'],['country','الدولة','text'],['event_date','تاريخ ووقت الحفلة','datetime-local']].map(([key,label,type])=><label key={key}>{label}<input required type={type} value={event[key]||''} onChange={e=>update(String(key),e.target.value)}/></label>)}</div><label>وصف الحفلة<textarea value={event.description||''} onChange={e=>update('description',e.target.value)}/></label></section>{error&&<div className="form-message">{error}</div>}{notice&&<div className="success-message">{notice}</div>}<button className="pay-btn" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ التعديلات'}</button></form><section className="admin-content-card"><h3><Ticket size={18}/> ملخص أنواع التذاكر</h3>{event.ticket_types?.length?event.ticket_types.map((ticket:any)=><div className="event-editor-ticket" key={ticket.id}><b>{ticket.name}</b><span>{money(ticket.price,ticket.currency)}</span><span>{Number(ticket.quantity_available)-Number(ticket.quantity_sold)-Number(ticket.quantity_reserved)} متاحة</span></div>):<p>لا توجد أنواع تذاكر لهذه الحفلة.</p>}</section></div>;
}
function EventManager({ archive, onEdit }: { archive: (id:string)=>void; onEdit:(id:string)=>void }) {
  const [events, setEvents] = useState<any[]>([]); const [notice, setNotice] = useState(''); const [error, setError] = useState('');const [page,setPage]=useState(1);const [total,setTotal]=useState(0);const [addingEvent,setAddingEvent]=useState('');const pageSize=25;
  const load = () => fetch(`${API}/api/admin/events?page=${page}`, { credentials: 'include' }).then(r => r.json()).then(d => {setEvents(d.events || []);setTotal(d.total||0);}).catch(() => setError('تعذر تحميل الحفلات.'));
  useEffect(() => { load(); }, [page]);
  const createTicketType=async(event:React.FormEvent<HTMLFormElement>,eventItem:any)=>{event.preventDefault();const form=new FormData(event.currentTarget);try{const response=await fetch(`${API}/api/admin/events/${eventItem.id}/ticket-types`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:form.get('name'),price:form.get('price'),currency:form.get('currency'),quantity_available:form.get('quantity_available')})});const data=await response.json();if(!response.ok)throw new Error(data.error);setNotice(`تمت إضافة فئة ${data.ticket_type.name}.`);setAddingEvent('');await load();}catch(error:any){setError(error.message||'تعذر إضافة فئة التذكرة.');}};
  const saveTicket = async (e: React.FormEvent<HTMLFormElement>, ticket: any) => {
    e.preventDefault(); setError(''); setNotice(''); const form = new FormData(e.currentTarget);
    try {
      const r = await fetch(`${API}/api/admin/ticket-types/${ticket.id}`, { method: 'PUT', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ price: form.get('price'), currency: form.get('currency'), quantity_available: form.get('quantity_available') }) });
      const d = await r.json(); if (!r.ok) throw new Error(d.error); setNotice(`تم تحديث ${ticket.name}؛ المخزون المتاح الآن ${d.ticket_type.quantity_available}.`); await load();
    } catch (x: any) { setError(x.message || 'تعذر تحديث فئة التذكرة.'); }
  };
  return <div className="event-manager">{notice && <div className="success-message">{notice}</div>}{error && <div className="form-message">{error}</div>}<div className="manage-list">{events.map(e => <article key={e.id}><img src={e.image_url || '/hero-banner.png'} alt=""/><div className="manage-event-info"><b>{e.title}</b><button type="button" className="secondary-admin-btn event-edit-button" onClick={()=>onEdit(e.id)}>تعديل</button><small>{e.city} · {dateParts(e.event_date)}</small><small>{e.ticket_types?.length || 0} فئة تذكرة</small><details className="ticket-stock-details"><summary>إدارة فئات التذاكر</summary><div className="ticket-stock-list">{e.ticket_types?.map((ticket: any) => <form className="ticket-stock-form" key={ticket.id} onSubmit={event => saveTicket(event, ticket)}><strong className="ticket-name"><Ticket size={16}/>{ticket.name}</strong><label>السعر<input name="price" type="number" min="0" step="0.01" defaultValue={ticket.price}/></label><label>العملة<input name="currency" maxLength={3} pattern="[A-Za-z]{3}" defaultValue={ticket.currency.trim()} title="رمز العملة من ثلاثة أحرف"/></label><label>الكمية المتاحة<input name="quantity_available" type="number" min={Number(ticket.quantity_sold||0)+Number(ticket.quantity_reserved||0)} step="1" defaultValue={ticket.quantity_available}/></label><button type="submit">حفظ</button><small>تم بيع {ticket.quantity_sold} · المتاح للحجز {Math.max(0,ticket.quantity_available-ticket.quantity_sold)}</small></form>)}</div></details></div>{addingEvent===e.id?<form className="ticket-stock-form" onSubmit={event=>createTicketType(event,e)}><label>اسم الفئة<input name="name" required/></label><label>السعر<input name="price" type="number" min="0" step="0.01" required/></label><label>العملة<input name="currency" maxLength={3} defaultValue={e.ticket_types?.[0]?.currency?.trim()||"USD"} required/></label><label>الكمية<input name="quantity_available" type="number" min="1" defaultValue="100" required/></label><button type="submit">حفظ الفئة</button><button type="button" onClick={()=>setAddingEvent("")}>إلغاء</button></form>:<button type="button" onClick={()=>setAddingEvent(e.id)}>إضافة فئة تذكرة</button>}<button onClick={() => archive(e.id)}>أرشفة</button></article>)}{!events.length && <div className="empty-state">مافيش حفلات حاليًا. أضف أول حفلة من القائمة الجانبية.</div>}</div><Pagination page={page} total={total} pageSize={pageSize} onPage={setPage} label="حفلة"/></div>;
}
